{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Isocorydine, a structurally related aporphine alkaloid with the highest transfer likelihood, was detected in rat brain within 10 minutes of administration, directly demonstrating effective BBB crossing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Hernandezine, despite its large bisbenzylisoquinoline structure, reached a brain Cmax nearly equal to plasma Cmax after intravenous dosing in rats, showing robust CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Corynoline, a polycyclic alkaloid with methylenedioxy features similar to the query, traversed the BBB and achieved relatively high brain concentrations in mice.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nuciferine, an aporphine alkaloid, achieved brain tissue concentrations almost equal to plasma concentrations in rats, supporting meaningful CNS penetration for this alkaloid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Dauricine crosses the BBB in rats even though it is a P-glycoprotein substrate; P-gp inhibition increased brain levels, indicating that efflux liability does not preclude meaningful CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query molecule is a phthalideisoquinoline alkaloid closely related to multiple aporphine/protoberberine alkaloids that consistently show direct brain, CSF, or brain/plasma evidence of BBB penetration in rodents. The physicochemical prior also favors passive diffusion, and the only potential liability (tertiary amine/efflux) is not sufficient to negate access based on the strong transferable experimental evidence.",
  "evidence_gaps": [
    "No direct brain tumor or glioma-specific pharmacokinetic data for the query molecule.",
    "No direct P-gp/BCRP efflux measurement for the query molecule, though related alkaloids show efflux can coexist with meaningful CNS exposure.",
    "Most evidence is from healthy rodents rather than tumor-bearing or human conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

